require __DIR__.'/../config/database.php';require __DIR__.'/../includes/functions.php';require_role(['staff','admin']);
$sid=(int)($_GET['id']??$_POST['scholarship_id']??0);$q=$pdo->prepare('SELECT * FROM scholarships WHERE scholarship_id=?');$q->execute([$sid]);$scholarship=$q->fetch();if(!$scholarship){http_response_code(404);exit('Scholarship not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='save_document'){$id=(int)($_POST['requirement_id']??0);$name=trim($_POST['document_name']??'');$desc=trim($_POST['description']??'');$types=strtolower(trim($_POST['allowed_types']??'pdf'));$types=preg_replace('/[^a-z,]/','',$types);$max=(float)($_POST['max_size_mb']??5);$required=isset($_POST['set_required'])?(((string)$_POST['set_required']==='1')?1:0):((isset($_POST['is_required']) && (string)$_POST['is_required']==='1')?1:0);if($name===''||$max<0.1||$max>20||!preg_match('/^(pdf|jpg|jpeg|png)(,(pdf|jpg|jpeg|png))*$/',$types)){flash('Check the document name, allowed file types and file size.','error');redirect('application_builder.php?id='.$sid);}if($id){$q=$pdo->prepare('UPDATE scholarship_document_requirements SET document_name=?,description=?,is_required=?,allowed_types=?,max_size_mb=? WHERE requirement_id=? AND scholarship_id=?');$q->execute([$name,$desc,$required,$types,$max,$id,$sid]);}else{$q=$pdo->prepare('INSERT INTO scholarship_document_requirements(scholarship_id,document_name,description,is_required,allowed_types,max_size_mb) VALUES(?,?,?,?,?,?)');$q->execute([$sid,$name,$desc,$required,$types,$max]);}flash('Document requirement saved.');redirect('application_builder.php?id='.$sid);}
 if($action==='delete_document'){$q=$pdo->prepare('UPDATE scholarship_document_requirements SET is_active=0 WHERE requirement_id=? AND scholarship_id=?');$q->execute([(int)$_POST['requirement_id'],$sid]);flash('Document requirement removed.');redirect('application_builder.php?id='.$sid);}
 if($action==='save_question'){$id=(int)($_POST['question_id']??0);$text=trim($_POST['question_text']??'');$help=trim($_POST['help_text']??'');$type=$_POST['field_type']??'short_text';$required=isset($_POST['set_required'])?(((string)$_POST['set_required']==='1')?1:0):((isset($_POST['is_required']) && (string)$_POST['is_required']==='1')?1:0);$options=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',$_POST['options']??''))));if(!in_array($type,['short_text','long_text','number','date','select'],true)||$text===''){flash('Enter a question and select a valid answer type.','error');redirect('application_builder.php?id='.$sid);}if($type==='select'&&count($options)<2){flash('A dropdown question needs at least two options, one per line.','error');redirect('application_builder.php?id='.$sid);}$json=$type==='select'?json_encode($options,JSON_UNESCAPED_UNICODE):null;if($id){$q=$pdo->prepare('UPDATE scholarship_questions SET question_text=?,help_text=?,field_type=?,is_required=?,options_json=? WHERE question_id=? AND scholarship_id=?');$q->execute([$text,$help,$type,$required,$json,$id,$sid]);}else{$q=$pdo->prepare('INSERT INTO scholarship_questions(scholarship_id,question_text,help_text,field_type,is_required,options_json) VALUES(?,?,?,?,?,?)');$q->execute([$sid,$text,$help,$type,$required,$json]);}flash('Application question saved.');redirect('application_builder.php?id='.$sid);}
 if($action==='delete_question'){$q=$pdo->prepare('UPDATE scholarship_questions SET is_active=0 WHERE question_id=? AND scholarship_id=?');$q->execute([(int)$_POST['question_id'],$sid]);flash('Question removed.');redirect('application_builder.php?id='.$sid);}
}
$q=$pdo->prepare('SELECT * FROM scholarship_document_requirements WHERE scholarship_id=? AND is_active=1 ORDER BY sort_order,requirement_id');$q->execute([$sid]);$documents=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM scholarship_questions WHERE scholarship_id=? ORDER BY sort_order,question_id');$q->execute([$sid]);$questions=$q->fetchAll();
$pageTitle='Application Form Builder';require __DIR__.'/../includes/header.php';
